import React from "react";
import { Audio, getStaticFiles, interpolate, staticFile } from "remotion";
import { DURATION } from "../theme";

/**
 * Plays public/audio/soundtrack.wav when present (an original score generated by
 * tools/make_soundtrack.py — no third-party audio). Drop in any licensed track with
 * that name to replace it. If the file is absent the film renders silent.
 */
const FILE = "audio/soundtrack.wav";

export const Soundtrack: React.FC = () => {
  const has = getStaticFiles().some((f) => f.name === FILE);
  if (!has) return null;
  return (
    <Audio
      src={staticFile(FILE)}
      volume={(f) => interpolate(f, [0, 12, DURATION - 50, DURATION], [0, 0.9, 0.9, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" })}
    />
  );
};
